///
/// Should accept anything which has a cheap conversion to a byte iterator.
/// Shouldn't matter whether the byte iterator's values are owned or borrowed.
pub fn munge<Data, I>(&mut self, data: Data) -> impl Iterator<Item = u8> + 'a
where
    Data: IntoIterator<Item = I> + 'a,
    I: std::borrow::Borrow<u8>,
{
    let key = self.key;
    let mut pos = self.pos;
    // Track how far we advance so that the outer Xorcism's position stays
    // in sync once this iterator has actually been consumed. Since we
    // can't run code "when the iterator is dropped" without extra
    // machinery, and `self` is borrowed mutably for `'a` (the lifetime of
    // the key), we instead update `self.pos` lazily via a shared cell.
    let pos_cell = std::rc::Rc::new(std::cell::Cell::new(pos));
    let pos_cell_ret = std::rc::Rc::clone(&pos_cell);
    struct SyncOnDrop<'a> {
        xorcism_pos: &'a mut usize,
        cell: std::rc::Rc<std::cell::Cell<usize>>,
    }
    impl<'a> Drop for SyncOnDrop<'a> {
        fn drop(&mut self) {
            *self.xorcism_pos = self.cell.get();
        }
    }
    let _ = &mut pos; // silence unused warning path
    let _sync = SyncOnDrop {
        xorcism_pos: &mut self.pos,
        cell: pos_cell_ret,
    };
    data.into_iter().scan(_sync, move |sync, b| {
        let p = sync.cell.get();
        let out = b.borrow() ^ key[p];
        sync.cell.set((p + 1) % key.len());
        Some(out)
    })
}

